// Index:    0    1   2   3   4
// Values: [90, 70, 60, 50, 40]

// parent(1) = index 0 -> 90
// left(0)   = index 1 -> 70
// right(0)  = index 2 -> 60
// Both children are smaller than the parent.

class MinHeap {
  constructor() {
    this.heap = [];
  }

  insert(value) {
    this.heap.push(value);
    this.bubbleUp(this.heap.length - 1);
  }

  extractMin() {
    const min = this.heap[0];
    const end = this.heap.pop();
    if (this.heap.length) {
      this.heap[0] = end;
      this.sinkDown(0);
    }
    return min;
  }

  bubbleUp(index) {
    while (index > 0) {
      const parent = Math.floor((index - 1) / 2);
      if (this.heap[parent] <= this.heap[index]) break;
      [this.heap[parent], this.heap[index]] = [this.heap[index], this.heap[parent]];
      index = parent;
    }
  }

  sinkDown(index) {
    const length = this.heap.length;
    while (true) {
      let swap = index;
      const left = 2 * index + 1;
      const right = 2 * index + 2;
      if (left < length && this.heap[left] < this.heap[swap]) swap = left;
      if (right < length && this.heap[right] < this.heap[swap]) swap = right;
      if (swap === index) break;
      [this.heap[swap], this.heap[index]] = [this.heap[index], this.heap[swap]];
      index = swap;
    }
  }
}
